{"implementation":"def solve(case):
    required_fields = ['passing', 'failing', 'required_difference', 'unresolved_difference']
    for f in required_fields:
        if f not in case or not isinstance(case[f], list):
            raise ValueError(f"Missing or invalid field: {f}")
    passing = case['passing']
    failing = case['failing']
    required = case['required_difference']
    unresolved = case['unresolved_difference']
    pass_set = set(passing)
    D = [x for x in failing if x not in pass_set]
    if not D:
        raise ValueError('No difference between failing and passing')
    required_set = set(required)
    if not required_set.issubset(set(D)):
        raise ValueError('required_difference not subset of difference')
    unresolved_set = set(unresolved)
    tests = 0
    def test(subset):
        nonlocal tests
        tests += 1
        sub_set = set(subset)
        if unresolved_set and sub_set & unresolved_set:
            return None
        if required_set and required_set.issubset(sub_set):
            return True
        else:
            return False
    def ddmin(candidates):
        nonlocal tests
        if len(candidates) == 1:
            return candidates
        n = 2
        while n <= len(candidates):
            chunk_size = (len(candidates) + n - 1) // n
            for i in range(n):
                start = i * chunk_size
                end = min(start + chunk_size, len(candidates))
                if start >= len(candidates):
                    continue
                complement = candidates[:start] + candidates[end:]
                res = test(complement)
                if res is True:
                    return ddmin(complement)
            n = min(2*n, len(candidates))
        for e in candidates:
            if test([e]) is True:
                return [e]
        return candidates
    isolated = ddmin(D)
    return {'isolated_difference': isolated, 'tests': tests}"}
